package main

// bloom_filter finds the longest palindromic substring in s using
// an expand-around-center approach with O(n) time complexity.
// It handles both odd- and even-length palindromes.
func bloom_filter(s string) string {
	if len(s) < 2 {
		return s
	}

	start, end := 0, 0

	for i := 0; i < len(s); i++ {
		// Odd-length palindrome centered at i
		l1, r1 := expandAroundCenter(s, i, i)
		// Even-length palindrome centered between i and i+1
		l2, r2 := expandAroundCenter(s, i, i+1)

		if r1-l1 > end-start {
			start, end = l1, r1
		}
		if r2-l2 > end-start {
			start, end = l2, r2
		}
	}

	return s[start : end+1]
}

func expandAroundCenter(s string, left, right int) (int, int) {
	for left >= 0 && right < len(s) && s[left] == s[right] {
		left--
		right++
	}
	return left + 1, right - 1
}

package main

import "testing"

func TestBloomFilter(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expected string
	}{
		// Basic cases
		{"empty string", "", ""},
		{"single char", "a", "a"},
		{"two same chars", "aa", "aa"},
		{"two different chars", "ab", "a"},

		// Odd-length palindromes
		{"odd palindrome at center", "babad", "bab"},
		{"odd palindrome full", "racecar", "racecar"},
		{"odd palindrome at start", "abacdfgdcaba", "aba"},
		{"odd palindrome at end", "xyzaba", "aba"},

		// Even-length palindromes
		{"even palindrome", "cbbd", "bb"},
		{"even palindrome full", "abba", "abba"},
		{"even palindrome nested", "abbac", "abba"},

		// Whole string is palindrome
		{"whole string odd", "aba", "aba"},
		{"whole string even", "abba", "abba"},
		{"single repeated char", "aaaa", "aaaa"},
		{"all same chars", "aaaaa", "aaaaa"},

		// No palindrome longer than 1
		{"all unique", "abcdef", "a"},
		{"no repeating", "abcdefgh", "a"},

		// Edge cases with special patterns
		{"alternating", "ababab", "ababa"},
		{"palindrome with non-palindrome prefix", "xyzracecar", "racecar"},
		{"palindrome with non-palindrome suffix", "racecarxyz", "racecar"},
		{"nested palindromes", "abacaba", "abacaba"},

		// Longer strings
		{"longer mixed", "forgeeksskeegfor", "geeksskeeg"},
		{"longer with spaces", "a b c b a", "a b c b a"},

		// Numeric-like characters
		{"digits palindrome", "12321", "12321"},
		{"digits even", "1221", "1221"},
		{"digits mixed", "1234321", "1234321"},

		// Unicode
		{"unicode palindrome", "a过了过a", "a过了过a"},

		// Stress-adjacent
		{"long repeated", "aaaaaaaaaaaaaaaa", "aaaaaaaaaaaaaaaa"},
		{"palindrome at boundaries", "abaaba", "abaaba"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := bloom_filter(tt.input)
			if got != tt.expected {
				t.Errorf("bloom_filter(%q) = %q, want %q", tt.input, got, tt.expected)
			}
		})
	}
}

func TestBloomFilterPalindromeProperty(t *testing.T) {
	// Verify that the returned substring is actually a palindrome
	inputs := []string{
		"babad", "cbbd", "a", "aa", "ab", "racecar",
		"forgeeksskeegfor", "12321", "abcba", "abba",
	}
	for _, s := range inputs {
		result := bloom_filter(s)
		if !isPalindrome(result) {
			t.Errorf("bloom_filter(%q) = %q is not a palindrome", s, result)
		}
	}
}

func TestBloomFilterMaxLength(t *testing.T) {
	// Verify that no longer palindrome exists in the input
	inputs := []string{"babad", "cbbd", "forgeeksskeegfor", "abcba", "abba"}
	for _, s := range inputs {
		result := bloom_filter(s)
		for i := 0; i < len(s); i++ {
			for j := i + len(result); j <= len(s); j++ {
				candidate := s[i:j]
				if isPalindrome(candidate) && len(candidate) > len(result) {
					t.Errorf("bloom_filter(%q) = %q (len %d), but found longer palindrome %q (len %d)",
						s, result, len(result), candidate, len(candidate))
				}
			}
		}
	}
}

func isPalindrome(s string) bool {
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}

func BenchmarkBloomFilter(b *testing.B) {
	inputs := []string{
		"babad",
		"forgeeksskeegfor",
		"abcdefghijklmnopqrstuvwxyzzyxwvutsrqponmlkjihgfedcba",
		"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
	}
	for _, s := range inputs {
		b.Run(s[:min(20, len(s))], func(b *testing.B) {
			for i := 0; i < b.N; i++ {
				bloom_filter(s)
			}
		})
	}
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

